def pacific_atlantic_brute(heights):
    rows, cols = len(heights), len(heights[0])
    def can_reach(r, c, target_check, visited):
        if target_check(r, c):
            return True
        visited.add((r, c))
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r+dr, c+dc
            if (0<=nr<rows and 0<=nc<cols and (nr,nc) not in visited
                    and heights[nr][nc] <= heights[r][c]):                # only downhill
                if can_reach(nr, nc, target_check, visited):
                    return True
        return False
    result = []
    for r in range(rows):
        for c in range(cols):
            pac = can_reach(r, c, lambda rr, cc: rr==0 or cc==0, set())      # SEPARATE search per cell
            atl = can_reach(r, c, lambda rr, cc: rr==rows-1 or cc==cols-1, set())
            if pac and atl:
                result.append([r, c])
    return result

